arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Content-Type: application/x-www-form-urlencoded' --data-urlencode "token=<TOKEN>" --data-urlencode "types=public_channel,private_channel" --data-urlencode "exclude_archived=false" --data-urlencode "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for c in d['channels']:
    if 'release' in c['name'].lower() or 'deploy' in c['name'].lower():
        print(c['id'], c['name'], 'is_private' if c.get('is_private') else 'public', 'created', c['created'])
"

